using System.Text.Json.Serialization;
using ProductsApi.Services;

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddControllers()
    .AddJsonOptions(options =>
    {
        options.JsonSerializerOptions.Converters.Add(new JsonStringEnumConverter());
    });

builder.Services.AddOpenApi(options =>
{
    options.AddDocumentTransformer((document, context, ct) =>
    {
        document.Info.Title = "Products API";
        document.Info.Version = "v1";
        document.Info.Description = "An API for managing a product catalog with categories, pricing, and timestamps.";
        return Task.CompletedTask;
    });
});

builder.Services.AddSingleton<IProductService, InMemoryProductService>();

var app = builder.Build();

app.MapOpenApi();

if (app.Environment.IsDevelopment())
{
    app.UseSwaggerUI(options => options.SwaggerEndpoint("/openapi/v1.json", "Products API v1"));
}

app.MapControllers();

app.Run();

